/** Compose state seeded from the handle and written through to it on every change. */
private fun savedField(handle: SavedStateHandle, key: String): MutableState<String> {
    val state = mutableStateOf(handle.get<String>(key) ?: "")
    return object : MutableState<String> {
        override var value: String
            get() = state.value
            set(v) {
                state.value = v
                handle[key] = v
            }

        override fun component1() = value
        override fun component2(): (String) -> Unit = { value = it }
    }
}

